mapper.select:
SELECT count(*)
FROM owner_transfers
WHERE space_id = #{spaceId} AND from_user_id = #{userId} AND status = #{pendingStatus}

mapper.update:
UPDATE owner_transfers
SET status = #{completedStatus}
WHERE space_id = #{spaceId} AND event_id = #{eventId}
  AND from_user_id = #{userId} AND status = #{handoverStatus}
